import { createRouter, createWebHistory, RouteRecordRaw } from 'vue-router';
import { closeGlobalLoading } from '@/utils/common';
import { title, description, keywords } from '@/config/seo';
import { useHead } from '@vueuse/head';

const Index = () => import('@/views/LegoDesigner/index.vue');
const LegoDesigner = () => import('@/views/LegoDesigner/index.vue');
const PostWorkSuccess = () => import('@/views/LegoDesigner/postWordSuccess/index.vue');
const LegoTemplateList = () => import('@/views/legoTemplateList/index.vue');
const LegoPrintPdfPreview = () =>
  import('@/views/LegoDesigner/render/LegoPrintPdfPreview/index.vue');
const ImgCompress = () => import('@/views/imgCompress/index.vue');
const NotFoundPage = () => import('@/views/404/index.vue');

const routes: Array<RouteRecordRaw> = [
  {
    path: '/',
    name: 'Index',
    redirect: '/legoDesigner',
    meta: {
      title: title,
      keepAlive: true,
      isShowComNav: false
    }
  },
  {
    path: '/legoDesigner',
    name: 'LegoDesigner',
    meta: {
      title: '积木搭建',
      keepAlive: true,
      isShowComNav: false
    },
    component: LegoDesigner
  },
  {
    path: '/legoPrintPdfPreview',
    name: 'LegoPrintPdfPreview',
    meta: {
      title: '积木制作打印预览页',
      keepAlive: false,
      isShowComNav: false
    },
    component: LegoPrintPdfPreview
  },
  {
    path: '/legoTemplateList',
    name: 'LegoTemplateList',
    meta: {
      title: '积木模板列表',
      keepAlive: true,
      isShowComNav: true
    },
    component: LegoTemplateList
  },
  {
    path: '/postWorkSuccess',
    name: 'PostWorkSuccess',
    meta: {
      title: '作品保存成功',
      keepAlive: true,
      isShowComNav: true
    },
    component: PostWorkSuccess
  },
  {
    path: '/imgCompress',
    name: 'ImgCompress',
    meta: {
      title: '图片压缩工具',
      keepAlive: true,
      isShowComNav: true
    },
    component: ImgCompress
  },
  {
    path: '/:pathMatch(.*)*',
    name: 'NotFound',
    component: NotFoundPage
  }
];

const router = createRouter({
  history: createWebHistory(),
  routes,
  scrollBehavior(to, from, savedPosition) {
    if (savedPosition) {
      return savedPosition;
    }
    return { top: 0 };
  }
});

// 全局守卫
router.beforeEach(async (to, from, next) => {
  const isTemplatePage = location.pathname.endsWith('.html');
  if (!isTemplatePage) {
    useHead({
      title: '简历制作器 - ' + ((to.meta.title as string) || title),
      meta: [
        {
          name: 'description',
          content: to.meta?.description || description
        },
        {
          name: 'keywords',
          content: to.meta?.keywords || keywords
        }
      ]
    });
  }
  closeGlobalLoading();
  next();
});

export default router;
