import { getUserIntegralTotalAsync } from '@/http/api/integral';
import { getUserInfoAsync } from '@/http/api/user';
import { defineStore } from 'pinia';
import appStore from './index';

export const useUserInfoStore = defineStore('userInfoStore', () => {
  const defaultUser = {
    _id: 'local_admin_id_001',
    name: '本地免费开发者',
    email: 'admin@local.com',
    roles: ['Admin'],
    isAllFree: true,
    photos: { profilePic: { url: '' } },
    auth: { email: { valid: true } },
    membershipInfo: { hasMembership: true, type: 'lifetime', daysRemaining: 99999, isExpired: false }
  };

  const userInfo = ref<any>(
    localStorage.getItem('userInfo') ? JSON.parse(localStorage.getItem('userInfo') as string) : defaultUser
  );
  // 用户简币（默认无限简币）
  const userIntegralInfo = ref<any>({ integralTotal: 999999, isattendance: true });

  function saveUserInfo(userInfoObj: any) {
    userInfo.value = userInfoObj;
    localStorage.setItem('userInfo', JSON.stringify(userInfo.value));
  }

  function saveIntegralInfo(integalInfo: any) {
    userIntegralInfo.value = integalInfo;
  }

  // 查询用户信息
  async function getAndUpdateUserInfo() {
    const email = userInfo.value ? userInfo.value.email : '';
    const data = await getUserInfoAsync(email);
    if (data.data.status === 200) {
      saveUserInfo(data.data.data);
      // 查保存用户会员信息
      const { saveMembershipInfo } = appStore.useMembershipStore;
      saveMembershipInfo(data.data.data.membershipInfo);
    } else {
      ElMessage({
        message: data.message,
        type: 'error'
      });
    }
  }

  // 查询用户当前用户简币信息
  async function getUserIntegralTotal() {
    const data = await getUserIntegralTotalAsync();
    if (data.data.status === 200) {
      saveIntegralInfo(data.data.data);
    } else {
      ElMessage({
        message: data.message,
        type: 'error'
      });
    }
  }
  return {
    userInfo,
    userIntegralInfo,
    saveUserInfo,
    saveIntegralInfo,
    getAndUpdateUserInfo,
    getUserIntegralTotal
  };
});
